export const suspects=[{id:'clara',name:'Clara Whitmore',role:'Estate secretary',initials:'CW',statement:'“I left Sir Edmund at a quarter to ten. I did not return to that wing. I was with the others when his bell rang.”',motive:'Managed correspondence, compensation accounts and the duplicate-key register. Her livelihood depended on Edmund’s trust.',timeline:'9:45 — claimed last meeting. About 10:04 — gardener places her at the study corridor. 10:08–10:15 — Lady Blackthorn and a footman confirm her presence in the drawing room.',secret:'Her initials authorize payments larger than the families received. Her 10:15 alibi is genuine; what it proves depends on when the murder happened.'},{id:'julian',name:'Julian Blackthorn',role:'The son & heir',initials:'JB',statement:'“Yes, I wrote that letter. I was angry. I needed money, not a funeral.”',motive:'Gambling debts and a bitter argument about his inheritance.',timeline:'9:40 — argument with Edmund. 9:58–10:07 — billiard room, independently witnessed by Captain Shaw and footman Thomas Reed. 10:15 — follows the others to the study.',secret:'His concealed letter threatened to leave the family and sell his inheritance expectations. The original letter, found in his coat, says “You will lose your son”, not a threat to kill. His two witnesses cover the likely attack.'},{id:'ward',name:'Dr. Elias Ward',role:'Family physician',initials:'EW',statement:'“The kitchen maid burned her arm. Ask her, or the cook. I never left her until ten past.”',motive:'Feared Edmund would expose an affair and ruin his standing.',timeline:'9:55–10:10 — kitchen, dressing Alice’s burn; Alice and the cook both confirm continuous attendance. 10:18 — summoned to the study.',secret:'His medical bag contains ordinary instruments and medicine, but the injury is blunt-force trauma, not poisoning. The scandal explains his evasiveness; the witnesses account for his movements.'},{id:'agnes',name:'Mrs. Agnes Bell',role:'Housekeeper',initials:'AB',statement:'“A bell tells you someone wants attention. We never considered it might tell us nothing about who pulled it.”',motive:'Her late husband worked in Edmund’s factories. She resented the treatment of injured workers’ families.',timeline:'9:50–10:06 — linen inventory with maid Rose Finch. 10:06 onward — servants’ hall; Rose and the cook see her there when the bell rings at 10:15.',secret:'She hid the Hale family’s compensation letter to protect their private circumstances. With their permission it is now evidence: it confirms a short payment and helps expose the accounts.'}];
export const evidence={clock:{title:'The broken desk clock',label:'A / PHYSICAL EVIDENCE',text:'The heavy bronze desk clock lies beside the body, stopped at 10:02. Its casing is dented; blood traces remain in a recessed edge. The examiner identifies it as the likely weapon. The stopped hands suggest the moment of impact, but alone they cannot prove the time of death.'},gardener:{title:'A view from the conservatory',label:'B / SIGNED WITNESS STATEMENT',text:'“It was about four minutes past ten. I had just checked the conservatory clock. Miss Whitmore came out of the study corridor carrying a dark ledger under her arm. I stepped behind the palms. I should not have been inside; that is why I said nothing at first.” — Samuel Pike, gardener. His position gave him a clear view of the corridor’s only doorway. He did not witness the attack.'},key:{title:'The duplicate-key register',label:'C / ACCESS RECORD',text:'Register entry, 14 November: 8:40 PM — Duplicate study key issued to C. Whitmore for accounts work. No return entry. The conventional study lock can be locked from either side with a key. Edmund’s personal key was found on his desk; the windows were fastened from within. A duplicate key could lock the door from the corridor. The register establishes access, not guilt by itself.'},bell:{title:'The bell that came too late',label:'D / SCENE EXAMINATION',text:'At the study bell-pull: a short scorched thread, candle wax beneath the cord, a small brass counterweight on the floor and a fresh abrasion on the fitting. Together they support a delayed pull. The household heard the bell at 10:15; the physical reconstruction shows it could ring after someone left. A candle is not an exact timer.'},finance:{title:'The price of a silence',label:'E / ACCOUNTS & SIGNED RECEIPTS',text:'Edmund’s unsent letter to his solicitor: “Miss Whitmore shall account for these discrepancies tomorrow. I have secured the original entries.” Compare the recorded payments with signed family receipts. Select each discrepancy to add it to the notebook.'},search:{title:'Clara’s writing case',label:'F / CORROBORATING SEARCH',text:'A search justified by the payment discrepancies and Samuel Pike’s statement reveals the missing original ledger, the duplicate study key and a partially burned note in Clara’s hand: “Please postpone the solicitor’s visit. Give me until Friday to replace the difference.” The ledger records the actual lower payments. Its serial number matches the one listed in Edmund’s solicitor letter.'},medical:{title:'Examiner’s observations',label:'MEDICAL EXAMINATION / 10:24 PM',text:'Sir Edmund suffered a single fatal blunt-force injury. The wound is consistent with the heavy bronze clock’s edge. No evidence suggests poison or a medical instrument. Death preceded the examination, but the examiner cannot resolve a thirteen-minute interval precisely. Use the clock, independent movements and physical evidence together.'},floor:{title:'The ground-floor plan',label:'SURVEY / BLACKTHORN MANOR',text:'The study opens onto the east corridor, visible from the conservatory. That corridor leads to the entrance hall and drawing room. There is no secret passage. The study windows are fastened inside. The kitchen and servants’ hall are across the central hall; the billiard room is on the west side.'}};
export const payments=[['Hale family',40,15],['Bennett family',32,12],['Price family',28,10]];
export const deductions=[{id:'delay',name:'The bell did not prove life',a:'bell',b:'clock',text:'The clock suggests an earlier attack; physical traces show the bell could be pulled later by a falling weight. A 10:15 bell is not proof of a living occupant.'},{id:'door',name:'The locked room was staged',a:'key',b:'search',text:'The conventional lock, register and recovered duplicate explain how Clara could leave and lock the door while Edmund’s personal key stayed inside.'},{id:'lie',name:'The secretary’s account fails',a:'gardener',b:'search',text:'The gardener places Clara near the study with the ledger after her claimed departure. The stolen original in her writing case corroborates him; the financial records establish motive.'}];
export function canSearch(s){return s.found.includes('gardener')&&s.rows.length>0&&s.found.includes('finance')}
export function canAccuse(s){return deductions.every(d=>s.deductions.includes(d.id))}
export function correctAccusation(a){return a.suspect==='clara'&&a.method==='clock'&&a.motive==='fraud'&&['clock','gardener','key','bell','finance','search'].every(k=>a.proof.includes(k))}
